using System;
using System.Collections.Generic;
using Autodesk.Revit.DB;
using Antigravity.Core.Models;

namespace Antigravity.Core.Services
{
    public class CadParserService
    {
        public List<FoundationData> ExtractFoundationData(ImportInstance cadLink, string layerName)
        {
            var results = new List<FoundationData>();
            var doc = cadLink.Document;
            var geomElem = cadLink.get_Geometry(new Options());

            if (geomElem == null) return results;

            foreach (var geomObj in geomElem)
            {
                if (geomObj is GeometryInstance geomInst)
                {
                    var instanceGeom = geomInst.GetInstanceGeometry();

                    foreach (var geom in instanceGeom)
                    {
                        var styleId = geom.GraphicsStyleId;
                        if (styleId != ElementId.InvalidElementId)
                        {
                            var style = doc.GetElement(styleId) as GraphicsStyle;
                            if (style != null && style.GraphicsStyleCategory.Name.Equals(layerName, StringComparison.OrdinalIgnoreCase))
                            {
                                if (geom is GeometryInstance nestedInst)
                                {
                                    var transform = nestedInst.Transform;
                                    var origin = transform.Origin;
                                    var angle = transform.BasisX.AngleTo(XYZ.BasisX);
                                    if (transform.BasisX.Y < 0) angle = -angle;

                                    results.Add(new FoundationData 
                                    { 
                                        Center = origin, 
                                        RotationAngle = angle 
                                    });
                                }
                                else if (geom is PolyLine polyLine)
                                {
                                    var pts = polyLine.GetCoordinates();
                                    if (pts.Count > 0)
                                    {
                                        double minX = double.MaxValue, minY = double.MaxValue, minZ = double.MaxValue;
                                        double maxX = double.MinValue, maxY = double.MinValue, maxZ = double.MinValue;
                                        double maxLen = 0;
                                        XYZ longestEdge = XYZ.BasisX;
                                        var edges = new List<double>();

                                        for (int i = 0; i < pts.Count - 1; i++)
                                        {
                                            var pt = pts[i];
                                            if (pt.X < minX) minX = pt.X;
                                            if (pt.Y < minY) minY = pt.Y;
                                            if (pt.Z < minZ) minZ = pt.Z;
                                            if (pt.X > maxX) maxX = pt.X;
                                            if (pt.Y > maxY) maxY = pt.Y;
                                            if (pt.Z > maxZ) maxZ = pt.Z;

                                            var p2 = pts[i+1];
                                            var len = pt.DistanceTo(p2);
                                            edges.Add(len);
                                            if (len > maxLen) { maxLen = len; longestEdge = (p2 - pt).Normalize(); }
                                        }

                                        var lastPt = pts[pts.Count - 1];
                                        if (lastPt.X < minX) minX = lastPt.X;
                                        if (lastPt.Y < minY) minY = lastPt.Y;
                                        if (lastPt.Z < minZ) minZ = lastPt.Z;
                                        if (lastPt.X > maxX) maxX = lastPt.X;
                                        if (lastPt.Y > maxY) maxY = lastPt.Y;
                                        if (lastPt.Z > maxZ) maxZ = lastPt.Z;

                                        var center = new XYZ((minX + maxX) / 2, (minY + maxY) / 2, (minZ + maxZ) / 2);

                                        var angle = longestEdge.AngleTo(XYZ.BasisX);
                                        if (longestEdge.Y < 0) angle = -angle;

                                        edges.Sort();
                                        double length = 0, width = 0;
                                        if (edges.Count >= 4) {
                                            length = (edges[edges.Count - 1] + edges[edges.Count - 2]) / 2;
                                            width = (edges[edges.Count - 3] + edges[edges.Count - 4]) / 2;
                                        } else if (edges.Count > 0) {
                                            length = edges[edges.Count - 1];
                                            width = edges.Count > 1 ? edges[edges.Count - 2] : length;
                                        }

                                        results.Add(new FoundationData { Center = center, RotationAngle = angle, Length = length, Width = width });
                                    }
                                }
                            }
                        }
                    }
                }
            }

            return results;
        }
    }
}

